window.docContents[230].resolve({"/Logic/#Logical-Foundations--Logic-in-Lean--Programming-with-Propositions":{"contents":"\n\nWhat does it mean to say that\n\"an element x occurs in a list l\"?* If l is the empty list, then x cannot occur in it,\n  so the property \"x appears in l\" is simply false.* Otherwise, l has the form [x' :: l'].\n  In this case, x occurs in l if it is equal to x'\n  or if it occurs in l'.\n\nWe can translate this directly into a straightforward recursive function\ntaken an element and a list and returning... a proposition!\n\ndef In {α : Type} (x : α) (xs : List α) : Prop :=\n  match xs with\n  | [] => False\n  | x' :: xs' => x = x' ∨ In x xs'\n\ntheorem In_nil {α} (x : α) : In x [] = False := rfl\n\ntheorem In_cons {α} (x x' : α) (xs : List α) : In x (x' :: xs) = (x = x' ∨ In x xs) := rfl\ndef In {α : Type} (x : α) (xs : List α) : Prop :=\n  match xs with\n  | [] => False\n  | x' :: xs' => x = x' ∨ In x xs'\n\ntheorem In_nil {α} (x : α) : In x [] = False := rfl\n\ntheorem In_cons {α} (x x' : α) (xs : List α) : In x (x' :: xs) = (x = x' ∨ In x xs) := rfl\ndef In {α : Type} (x : α) (xs : List α) : Prop :=\n  match xs with\n  | [] => False\n  | x' :: xs' => x = x' ∨ In x xs'\n\ntheorem In_nil {α} (x : α) : In x [] = False := rfl\n\ntheorem In_cons {α} (x x' : α) (xs : List α) : In x (x' :: xs) = (x = x' ∨ In x xs) := rfl\n\n\nWhen In is applied to a concrete list, it exapnds into a concrete sequence\nof nested disjunctions.\n\nexample : In 4 [1, 2, 3, 4, 5] := by\n  workinclass!\n    dsimp [In]; right; right; right; left; rfl\n\nexample (n : Nat) (h : In n [2, 4]) : ∃ n' : Nat, n = 2 * n' := by\n  workinclass!\n    dsimp [In] at h\n    obtain h | h | ⟨⟨⟩⟩ := h\n    case inl => exists 1\n    case inr.inl => exists 2\n    /- (Notice the use of the empty pattern to discharge the last case.) -/\nexample : In 4 [1, 2, 3, 4, 5] := by\n  all_goals\n    dsimp [In]; right; right; right; left; rfl\n\nexample (n : Nat) (h : In n [2, 4]) : ∃ n' : Nat, n = 2 * n' := by\n  all_goals\n    dsimp [In] at h\n    obtain h | h | ⟨⟨⟩⟩ := h\n    case inl => exists 1\n    case inr.inl => exists 2\n    /- (Notice the use of the empty pattern to discharge the last case.) -/\nexample : In 4 [1, 2, 3, 4, 5] := by\n  sorry\n\nexample (n : Nat) (h : In n [2, 4]) : ∃ n' : Nat, n = 2 * n' := by\n  sorry\n    /- (Notice the use of the empty pattern to discharge the last case.) -/\n\n\nWe can also reason about more generic statements involving In.\n\ntheorem In_map (α β : Type) (f : α → β) (xs : List α) (x : α) (h : In x xs) :\n    In (f x) (List.map f xs) := by\n  -- TERSE: FOLD\n  induction xs\n  case nil => rw [In_nil] at h; contradiction\n  case cons x' xs' ih =>\n    rw [In_cons] at h\n    obtain h | h := h\n    case inl => rw [h, List.map_cons, In_cons]; left; rfl\n    case inr => rw [List.map_cons, In_cons]; right; exact ih h\n  -- TERSE: /FOLD\ntheorem In_map (α β : Type) (f : α → β) (xs : List α) (x : α) (h : In x xs) :\n    In (f x) (List.map f xs) := by\n  -- TERSE: FOLD\n  induction xs\n  case nil => rw [In_nil] at h; contradiction\n  case cons x' xs' ih =>\n    rw [In_cons] at h\n    obtain h | h := h\n    case inl => rw [h, List.map_cons, In_cons]; left; rfl\n    case inr => rw [List.map_cons, In_cons]; right; exact ih h\n  -- TERSE: /FOLD\ntheorem In_map (α β : Type) (f : α → β) (xs : List α) (x : α) (h : In x xs) :\n    In (f x) (List.map f xs) := by\n  -- TERSE: FOLD\n  induction xs\n  case nil => rw [In_nil] at h; contradiction\n  case cons x' xs' ih =>\n    rw [In_cons] at h\n    obtain h | h := h\n    case inl => rw [h, List.map_cons, In_cons]; left; rfl\n    case inr => rw [List.map_cons, In_cons]; right; exact ih h\n  -- TERSE: /FOLD\n\n\n\n\n\n\n","context":"Logical Foundations\u0009Logic in Lean","header":"8.5. Programming with Propositions","id":"/Logic/#Logical-Foundations--Logic-in-Lean--Programming-with-Propositions"}});